#!/usr/bin/env python3
"""Adjusts the Android project generated by `flutter create` for Aurum VPN.

Run from the project root after `flutter create --platforms=android .`
"""
import os
import re
import shutil
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
ANDROID = os.path.join(ROOT, "android")


def read(p):
    with open(p, encoding="utf-8") as f:
        return f.read()


def write(p, s):
    with open(p, "w", encoding="utf-8") as f:
        f.write(s)
    print("patched", os.path.relpath(p, ROOT))


def vtuple(v):
    return tuple(int(x) for x in re.findall(r"\d+", v)[:3])


def patch_app_gradle():
    kts = os.path.join(ANDROID, "app", "build.gradle.kts")
    groovy = os.path.join(ANDROID, "app", "build.gradle")
    if os.path.exists(kts):
        p, is_kts = kts, True
    elif os.path.exists(groovy):
        p, is_kts = groovy, False
    else:
        sys.exit("app gradle file not found")
    s = read(p)

    # Native libs of the Xray core must stay uncompressed/extractable.
    if "useLegacyPackaging" not in s:
        block = (
            "\n    packaging {\n        jniLibs {\n            useLegacyPackaging = true\n        }\n    }\n"
            if is_kts
            else "\n    packagingOptions {\n        jniLibs {\n            useLegacyPackaging = true\n        }\n    }\n"
        )
        s = re.sub(r"android\s*\{", lambda m: m.group(0) + block, s, count=1)

    # minSdk 24 (camera scanner + VPN core).
    if is_kts:
        s = re.sub(r"minSdk\s*=\s*[^\n]+", "minSdk = 24", s, count=1)
    else:
        s = re.sub(r"minSdk(Version)?\s+[^\n]+", "minSdkVersion 24", s, count=1)

    # Keep the release build simple: no code shrinking (gomobile JNI classes).
    if "isMinifyEnabled" not in s and "minifyEnabled" not in s:
        if is_kts:
            s = re.sub(
                r"(release\s*\{)",
                r"\1\n            isMinifyEnabled = false\n            isShrinkResources = false",
                s,
                count=1,
            )
        else:
            s = re.sub(
                r"(release\s*\{)",
                r"\1\n            minifyEnabled false\n            shrinkResources false",
                s,
                count=1,
            )
    s = patch_signing(s, is_kts)
    write(p, s)


def patch_signing(s, is_kts):
    """Release-sign with the project keystore when CI provides its password."""
    ks_pass = os.environ.get("KS_PASS", "")
    enc = os.path.join(ROOT, "android_overrides", "aida.jks.enc")
    if not ks_pass or not os.path.exists(enc):
        print("signing: no KS_PASS, keeping debug signing")
        return s
    out = os.path.join(ANDROID, "app", "aida.jks")
    rc = os.system(
        f'openssl enc -d -aes-256-cbc -pbkdf2 -iter 200000 -in "{enc}" -out "{out}" -pass env:KS_PASS'
    )
    if rc != 0 or not os.path.exists(out):
        sys.exit("signing: could not decrypt keystore (wrong KS_PASS?)")
    if is_kts:
        block = (
            '\n    signingConfigs {\n        create("aida") {\n            storeFile = file("aida.jks")\n'
            '            storePassword = System.getenv("KS_PASS")\n            keyAlias = "aida"\n'
            '            keyPassword = System.getenv("KS_PASS")\n            storeType = "PKCS12"\n        }\n    }\n'
        )
        s = re.sub(r"android\s*\{", lambda m: m.group(0) + block, s, count=1)
        s = s.replace('signingConfig = signingConfigs.getByName("debug")', 'signingConfig = signingConfigs.getByName("aida")')
    else:
        block = (
            "\n    signingConfigs {\n        aida {\n            storeFile file('aida.jks')\n"
            "            storePassword System.getenv('KS_PASS')\n            keyAlias 'aida'\n"
            "            keyPassword System.getenv('KS_PASS')\n            storeType 'PKCS12'\n        }\n    }\n"
        )
        s = re.sub(r"android\s*\{", lambda m: m.group(0) + block, s, count=1)
        s = s.replace("signingConfig signingConfigs.debug", "signingConfig signingConfigs.aida")
    print("signing: release keystore enabled")
    return s


def patch_settings_gradle():
    for name in ("settings.gradle.kts", "settings.gradle"):
        p = os.path.join(ANDROID, name)
        if not os.path.exists(p):
            continue
        s = read(p)
        m = re.search(r'id\("com\.android\.application"\)\s*version\s*"([^"]+)"', s) or re.search(
            r"id\s+['\"]com\.android\.application['\"]\s+version\s+['\"]([^'\"]+)['\"]", s
        )
        if m and vtuple(m.group(1)) < (8, 13, 0):
            s = s[: m.start(1)] + "8.13.0" + s[m.end(1):]
            write(p, s)
            bump_wrapper((8, 14))
        return


def bump_wrapper(minimum):
    p = os.path.join(ANDROID, "gradle", "wrapper", "gradle-wrapper.properties")
    if not os.path.exists(p):
        return
    s = read(p)
    m = re.search(r"gradle-([\d.]+)-(all|bin)\.zip", s)
    if m and vtuple(m.group(1)) < minimum:
        s = s.replace(m.group(0), "gradle-8.14-all.zip")
        write(p, s)


def patch_gradle_properties():
    p = os.path.join(ANDROID, "gradle.properties")
    s = read(p) if os.path.exists(p) else ""
    # Removed in AGP 8.1+; keep the file clean if a template adds it.
    if "enableUncompressedNativeLibs" in s:
        s = "\n".join(l for l in s.splitlines() if "enableUncompressedNativeLibs" not in l) + "\n"
        write(p, s)


def patch_manifest():
    p = os.path.join(ANDROID, "app", "src", "main", "AndroidManifest.xml")
    s = read(p)
    s = re.sub(r'android:label="[^"]*"', 'android:label="No VPN"', s, count=1)
    if "xmlns:tools" not in s:
        s = s.replace("<manifest ", '<manifest xmlns:tools="http://schemas.android.com/tools" ', 1)
    # No cloud/adb backups of settings and tokens.
    if "android:allowBackup" not in s:
        s = s.replace("<application", '<application\n        android:allowBackup="false"\n        android:fullBackupContent="false"', 1)
    # The core plugin asks for storage access the app never uses.
    if "READ_EXTERNAL_STORAGE" not in s:
        s = re.sub(r"(<manifest[^>]*>\s*\n)", lambda m: m.group(1) + '    <uses-permission android:name="android.permission.READ_EXTERNAL_STORAGE" tools:node="remove" />\n', s, count=1)
    perms = [
        "android.permission.INTERNET",
        "android.permission.ACCESS_NETWORK_STATE",
        "android.permission.CAMERA",
        "android.permission.POST_NOTIFICATIONS",
    ]
    add = "".join(
        f'    <uses-permission android:name="{x}" />\n' for x in perms if x not in s
    )
    if add:
        s = re.sub(r"(<manifest[^>]*>\s*\n)", lambda m: m.group(1) + add, s, count=1)
    write(p, s)


def copy_icons():
    src = os.path.join(ROOT, "android_overrides", "res")
    dst = os.path.join(ANDROID, "app", "src", "main", "res")
    for d in os.listdir(src):
        os.makedirs(os.path.join(dst, d), exist_ok=True)
        for f in os.listdir(os.path.join(src, d)):
            shutil.copyfile(os.path.join(src, d, f), os.path.join(dst, d, f))
    adaptive = os.path.join(dst, "mipmap-anydpi-v26")
    if os.path.isdir(adaptive):
        shutil.rmtree(adaptive)
    print("icons copied")


if __name__ == "__main__":
    patch_app_gradle()
    patch_settings_gradle()
    patch_gradle_properties()
    patch_manifest()
    copy_icons()
